  export default "/*\n * Copyright (c) 2023 Yookue Ltd. All rights reserved.\n *\n * Licensed under the MIT License (the \"License\")\n *\n * Permission is hereby granted, free of charge, to any person obtaining a copy\n * of this software and associated documentation files (the \"Software\"), to deal\n * in the Software without restriction, including without limitation the rights\n * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n * copies of the Software, and to permit persons to whom the Software is\n * furnished to do so, subject to the following conditions:\n *\n * The above copyright notice and this permission notice shall be included in all\n * copies or substantial portions of the Software.\n */\n\n\nimport React from 'react';\nimport {Row, Col, Divider} from 'antd';\nimport datePickerLocale from 'antd/es/date-picker/locale/zh_TW';\nimport {ProForm, ProFormDatePicker, ProFormRadio, ProFormSwitch, ProFormDependency} from '@ant-design/pro-form';\nimport {CompactTuple, type BeforeAfterType} from '@yookue/ant-buddy-pro';\nimport {type TuplePresetStyle} from '@yookue/ant-buddy-pro/field/CompactTuple';\nimport dayjs from 'dayjs';\n\n\nexport default () => {\n    // noinspection DuplicatedCode\n    const [formReadonly, setFormReadonly] = React.useState<boolean>(false);\n    const [widthBlock, setWidthBlock] = React.useState<boolean>(false);\n    const [addonPos, setAddonPos] = React.useState<BeforeAfterType>('after');\n    const [presetStyle, setPresetStyle] = React.useState<TuplePresetStyle | false>('field-prior');\n\n    return (\n        <>\n            <ProForm\n                name='CompactTuple_demo.zh-TW'\n                layout='horizontal'\n                autoFocusFirstInput={false}\n                submitter={false}\n            >\n                <ProForm.Group>\n                    <ProFormSwitch\n                        label='表單只讀'\n                        checkedChildren='是'\n                        unCheckedChildren='否'\n                        fieldProps={{\n                            checked: formReadonly,\n                            onChange: setFormReadonly,\n                        }}\n                    />\n                    <ProFormSwitch\n                        label='匹配寬度'\n                        checkedChildren='是'\n                        unCheckedChildren='否'\n                        fieldProps={{\n                            checked: widthBlock,\n                            onChange: setWidthBlock,\n                        }}\n                    />\n                </ProForm.Group>\n                <ProFormRadio.Group\n                    label='附加物位置'\n                    radioType='button'\n                    fieldProps={{\n                        value: addonPos,\n                        buttonStyle: 'solid',\n                        disabled: formReadonly,\n                        onChange: (event) => {\n                            setAddonPos(event.target?.value);\n                        }\n                    }}\n                    options={[\n                        {label: '前', value: 'before'},\n                        {label: '後', value: 'after'},\n                        {label: '無', value: false},\n                    ]}\n                />\n                <ProFormRadio.Group\n                    label='預設樣式'\n                    radioType='button'\n                    fieldProps={{\n                        value: presetStyle,\n                        buttonStyle: 'solid',\n                        disabled: formReadonly,\n                        onChange: (event) => {\n                            setPresetStyle(event.target?.value);\n                        }\n                    }}\n                    options={[\n                        {label: '字段優先', value: 'field-prior'},\n                        {label: '附加物優先', value: 'addon-prior'},\n                        {label: '無', value: false},\n                    ]}\n                />\n            </ProForm>\n            <Divider/>\n            <ProForm\n                name='CompactTuple_test'\n                layout='vertical'\n                autoFocusFirstInput={false}\n                readonly={formReadonly}\n                submitter={false}\n            >\n                <Row gutter={[12, 0]}>\n                    <Col span={12}>\n                        <ProFormDatePicker\n                            name='identityStart'\n                            label='開始日期'\n                            placeholder='開始日期'\n                            fieldProps={{\n                                style: {width: '100%'},\n                                locale: datePickerLocale,\n                            }}\n                        />\n                    </Col>\n                    <Col span={12}>\n                        <CompactTuple\n                            field={(\n                                <ProFormDependency name={['identityStart', 'identityInfinite']} shouldUpdate={true}>\n                                    {({identityStart, identityInfinite}) => {\n                                        return (\n                                            <ProFormDatePicker\n                                                name='identityEnd'\n                                                label='結束日期'\n                                                placeholder='結束日期'\n                                                fieldProps={{\n                                                    disabled: identityInfinite,\n                                                    disabledDate: (date: any) => date < dayjs(identityStart),\n                                                    style: {width: '100%'},\n                                                    locale: datePickerLocale,\n                                                }}\n                                            />\n                                        );\n                                    }}\n                                </ProFormDependency>\n                            )}\n                            addon={(\n                                <ProFormSwitch\n                                    name='identityInfinite'\n                                    label='長期'\n                                    fieldProps={{\n                                        defaultChecked: false,\n                                        checkedChildren: '是',\n                                        unCheckedChildren: '否',\n                                        style: {\n                                            margin: '2px 6px',\n                                        }\n                                    }}\n                                />\n                            )}\n                            addonPos={addonPos}\n                            addonBorder={true}\n                            addonMarginLeft={addonPos === 'after'}\n                            addonMarginRight={addonPos === 'before'}\n                            widthBlock={widthBlock}\n                            presetStyle={presetStyle}\n                        />\n                    </Col>\n                </Row>\n            </ProForm>\n        </>\n    );\n}\n";;
  